/** Terms indexed by id. A Map, never a plain object: term ids are outside data. */
export const TERM_BY_ID = new Map(TERMS.map((t) => [t.id, t]))

/** Ordered module list with their terms attached. */
export function termsByModule() {
  return MODULES.map((m) => ({ ...m, terms: TERMS.filter((t) => t.mod === m.id) }))
}
